<script setup>
import {computed} from 'vue';import {useRoute} from 'vue-router';import source from '../content/blueprint-pages.json';import team from '../content/team.json';import photos from '../content/photo-sources.json';
const route=useRoute();const title=computed(()=>route.meta.title);const blocks=computed(()=>{const lines=source[route.path]||[];return lines.filter(line=>line&& !/^(Meta |Page title:|Hero title:|Hero subtitle:|Last updated:|Notice for the team:|Banner text:|Field \||Buttons:)/.test(line)).map(line=>line.replace(/^(Intro|Title|Subtitle|Headline|Text|Our mission): /,''));});
const sections=computed(()=>{const result=[];let current={title:'Overview',lines:[]};for(const line of blocks.value){if((/^\d+\. |^(Our story|Why the name\?|Our mission|Our vision|Our values|Data|What |Your choices|Known limitations|Tell us)/.test(line))&&line.length<100){if(current.lines.length)result.push(current);current={title:line,lines:[]};}else current.lines.push(line);}if(current.lines.length)result.push(current);return result;});
function contentParts(lines){const parts=[];for(const line of lines){if(line.includes(' | ')){const last=parts[parts.length-1];if(last?.type==='table')last.rows.push(line.split(' | '));else parts.push({type:'table',rows:[line.split(' | ')]});}else parts.push({type:'paragraph',text:line});}return parts;}
const features=[['Search and filter','Search by restaurant name, cuisine or dish and narrow by region, country, price, dietary tags and review rating.'],['Best Quality','MongoDB adds recorded grade scores and ranks totals greater than 90.'],['Country guides','Eight guides explain signature dishes, meals, etiquette, tipping, festivals and useful phrases.'],['Owner tools','Owners add listings, claim restaurants and edit their own profiles. Staff approve claims and new listings.'],['Community','Verified accounts post reviews, report information and suggest edits.'],['Saved and compare','Keep a shortlist in your browser, sync account favorites and compare up to three restaurants.'],['Dashboards','Admins manage messages, reviews, users and activity logs; owners see their listings and counters.'],['Insights','Explore MongoDB group-by results through charts and accessible data tables.']];
const links=[['Home','/'],['About','/about'],['Features','/features'],['How It Works','/how-it-works'],['Restaurants','/restaurants'],['Suggest a Restaurant','/suggest-restaurant'],['Best Quality','/best-quality'],['Countries','/countries'],['Cuisines','/cuisines'],['Insights','/insights'],['Guides','/guides'],['Surprise Me','/surprise'],['Compare','/compare'],['Saved','/saved'],['Recently viewed','/recent'],['Trending','/trending'],['Newly Added','/new'],['Top Rated','/top-rated'],['Dishes','/dishes'],['Festivals','/festivals'],['Team','/team'],['FAQs','/faqs'],['Contact','/contact'],['Terms of Use','/terms'],['Privacy Policy','/privacy'],['Cookie Policy','/cookies'],['Accessibility','/accessibility'],['Login','/login'],['Register','/register'],['Owner Registration','/register/owner'],['Account','/account'],['Owner Dashboard','/owner'],['Admin Dashboard','/admin'],['Photo credits','/photo-credits']];
</script>
<template><div class="container section"><div class="page-head"><p class="eyebrow muted">BonAppé Find</p><h1>{{title}}</h1></div><template v-if="route.path==='/features'"><p>One complete student project: discovery, food culture, community and restaurant management.</p><div class="grid"><article v-for="[name,text] in features" :key="name" class="card pad"><h2>{{name}}</h2><p>{{text}}</p></article></div></template><template v-else-if="route.path==='/team'"><p>Four students. One table. Built for 6ADDBASE and 6WCSERVER.</p><div class="grid two"><article v-for="m in team" :key="m.name" class="card pad"><div class="avatar" aria-hidden="true">{{m.name.split(' ').map(n=>n[0]).join('')}}</div><h2>{{m.name}}</h2><p><b>{{m.role}}</b></p><p>{{m.bio}}</p></article></div></template><template v-else-if="route.path==='/sitemap'"><div class="grid"><RouterLink v-for="[name,url] in links" :key="url" :to="url" class="card pad">{{name}} →</RouterLink></div></template><template v-else-if="route.path==='/thank-you'"><p>Your submission has been received. Why not find something delicious?</p><div class="row"><RouterLink to="/restaurants" class="btn">Browse Restaurants</RouterLink><RouterLink to="/" class="btn secondary">Back to Home</RouterLink></div></template><template v-else-if="route.path==='/how-it-works'"><img class="process-cover" src="/images/photos/bistro.jpg" alt="A restaurant dining room ready to welcome guests" loading="lazy"><div class="grid"><article v-for="[n,name,text] in [['01','Search','Choose a restaurant name or cuisine. Filter by location, price and dietary needs.'],['02','Compare','Read the grades and check the review ratings. Save a shortlist or compare up to three profiles.'],['03','Enjoy','Read the country guide and confirm the hours, address and details with the restaurant.']]" :key="n" class="card pad"><p class="stat">{{n}}</p><h2>{{name}}</h2><p>{{text}}</p></article></div></template><template v-else-if="['/terms','/privacy','/cookies','/accessibility','/about'].includes(route.path)"><div class="info-layout"><aside class="info-sidebar"><img src="/images/photos/table.jpg" alt="An elegantly plated meal at a restaurant" loading="lazy"><div class="card pad"><p class="eyebrow">On this page</p><nav aria-label="Page contents"><a v-for="(section,i) in sections" :key="i" :href="'#info-'+i">{{section.title}}</a><a v-if="route.path!=='/about'" href="#additional-details">Additional details</a></nav><RouterLink to="/contact" class="btn secondary small">Have a question?</RouterLink></div></aside><article class="prose"><p class="muted small" v-if="route.path!=='/about'">Last updated: October 2026 · Educational project</p><section v-for="(section,i) in sections" :key="i" :id="'info-'+i" class="card pad info-section"><p class="eyebrow">{{String(i+1).padStart(2,'0')}}</p><h2>{{section.title}}</h2><template v-for="(part,j) in contentParts(section.lines)" :key="j"><div v-if="part.type==='table'" class="table-wrap"><table><caption class="sr-only">{{section.title}}</caption><thead><tr><th v-for="(cell,k) in part.rows[0]" :key="k" scope="col">{{cell}}</th></tr></thead><tbody><tr v-for="(row,n) in part.rows.slice(1)" :key="n"><td v-for="(cell,k) in row" :key="k">{{cell}}</td></tr></tbody></table></div><p v-else>{{part.text}}</p></template></section><div id="additional-details" class="info-additional"><section v-if="route.path==='/terms'"><h3>Accounts, claims and moderation</h3><p>Reviews require a verified account. Owners may edit listings they own. New owner listings and ownership claims require staff approval. Restaurant deletion moves the listing to Trash for staff restoration.</p></section><section v-if="route.path==='/privacy'"><h3>Implementation details</h3><p>Passwords are hashed with bcrypt. Saved lists, comparisons, recent views, search history, drafts, theme and a session token use browser storage. Account favorites and reviews are stored in MongoDB. Login history and audit logs record account actions, timestamps and IP addresses. Contact messages expire after twelve months. Email verification and password reset require configured email delivery; local development prints links in the server terminal.</p></section><section v-if="route.path==='/cookies'"><h3>Additional browser storage</h3><p>This implementation also stores your theme, recent views, searches, form drafts and a session identifier. You can clear them through your browser settings. A login token can remain until its expiry or logout.</p></section></div></article></div></template><template v-else-if="route.path==='/photo-credits'"><p>Restaurant and food photography bundled with this project. These stock images illustrate dining themes; they do not depict the fictional restaurants in this project.</p><p>All photos below are included locally in the project.</p><div class="grid"><article v-for="photo in photos" :key="photo.file" class="card"><img class="editorial-photo" :src="photo.source" :alt="(photo.dish||photo.file.replace('.jpg',''))+' photography'" loading="lazy"><div class="pad"><h2>{{photo.name||photo.file.replace('.jpg','')}}</h2><a :href="photo.source" target="_blank" rel="noopener noreferrer">View local photo ↗</a><p class="small muted">Bundled stock photograph.</p></div></article></div></template><template v-else><h2>This page is not on the menu</h2><p>The page you are looking for does not exist or has moved.</p><div class="row"><RouterLink to="/" class="btn">Back to Home</RouterLink><RouterLink to="/restaurants" class="btn secondary">Browse Restaurants</RouterLink></div></template></div></template>
<style scoped>.process-cover{width:100%;height:280px;object-fit:cover;border-radius:24px;margin-bottom:32px}.info-layout{display:grid;grid-template-columns:280px minmax(0,1fr);gap:48px}.info-sidebar{position:sticky;top:180px;align-self:start}.info-sidebar>img{width:100%;height:200px;object-fit:cover;border-radius:20px;margin-bottom:24px}.info-sidebar nav{display:grid;gap:14px;margin-bottom:24px;font-size:14px}.info-section{margin-bottom:24px;scroll-margin-top:190px}.info-section h2{font-size:30px}.info-additional{padding:8px 28px}#additional-details{scroll-margin-top:190px}@media(max-width:900px){.info-layout{grid-template-columns:minmax(0,1fr);gap:24px;width:100%;max-width:100%}.info-layout>*{min-width:0;max-width:100%}.info-sidebar{position:static}.info-sidebar .card.pad{overflow:hidden}.info-sidebar nav{max-width:100%}.prose{min-width:0}.info-sidebar>img{height:220px}}@media(max-width:900px){.info-sidebar>img{height:150px;margin-bottom:14px}.info-sidebar .card.pad{padding:14px 16px}.info-sidebar nav{display:flex;flex-direction:column;gap:8px;overflow:visible;margin:0 0 16px;padding:0}.info-sidebar nav a{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;min-height:48px;padding:12px 16px;border:1.5px solid var(--color-border);border-radius:14px;background:var(--color-bg);font-size:15px;font-weight:700;line-height:1.3;text-decoration:none;white-space:normal}.info-sidebar nav a::after{content:'\2192';flex:none;opacity:.55}.info-sidebar .btn{width:100%;box-sizing:border-box;text-align:center;justify-content:center;white-space:normal}.info-section{scroll-margin-top:100px}#additional-details{scroll-margin-top:100px}.info-section .table-wrap table{min-width:0!important;width:100%}.info-section .table-wrap td,.info-section .table-wrap th{padding:10px 12px;font-size:14px}.info-section .table-wrap td:first-child{min-width:0!important;font-weight:700}}
@media(max-width:600px){.info-layout{gap:16px}.info-section.card.pad,.info-section{padding:20px 18px}.info-section h2{font-size:24px}.info-additional{padding:4px 2px}.prose h3{margin-top:22px}}
.avatar{width:70px;height:70px;border-radius:50%;display:grid;place-items:center;background:var(--forestry);color:var(--candle);font-size:24px;margin-bottom:20px}.prose p{white-space:pre-line;overflow-wrap:anywhere}</style>
